import heapq

def min_rooms(meetings):
    if not meetings:
        return 0
    meetings = sorted(meetings)
    heap = []
    for s, e in meetings:
        if heap and heap[0] <= s:
            heapq.heapreplace(heap, e)
        else:
            heapq.heappush(heap, e)
    return len(heap)
